package dev.kayomarz.studyfeed.pack

import android.database.sqlite.SQLiteDatabase
import android.database.sqlite.SQLiteException
import org.json.JSONObject
import java.io.File

/**
 * Opens a content pack read-only and reads its self-description (BUILD_PROMPT §8 A1, spec/SPEC.md §3).
 *
 * **Raw SQLite, not Room — deliberately (plan D1).** Room's value is schema verification and
 * migrations, and the pack has neither: it is generated by the compiler, never written by the app, and
 * replaced wholesale on re-import. Room here would buy nothing and fight the `ATTACH` the feed needs
 * (plan D4). Room owns `progress_<EXAM>.db` and only that.
 *
 * **The gate runs before anything else is read** (§8 A1: "verify them before opening anything else"), so
 * a pack whose schema we don't understand never reaches a content query — which is precisely the case a
 * naive loader corrupts by silently mis-reading a renamed column.
 */
object PackDatabase {

    /** What the app gets back from a successful open. */
    data class LoadedPack(
        val manifest: PackManifest,
        val capabilities: PackCapabilities,
        val subjects: List<Subject>,
        val tags: List<TagDef>,
    )

    /** A subject chip. Built from the pack — the app has no idea what subjects any exam has. */
    data class Subject(val id: Long, val name: String, val blueprintWeight: Double, val ord: Int)

    /** A tag chip. Same: the pack defines its own tags, the app just renders them. */
    data class TagDef(val id: Long, val key: String, val label: String, val color: String?, val ord: Int)

    sealed interface Result {
        data class Ok(val pack: LoadedPack) : Result
        /** Refused by the gate, or unreadable. [message] is user-facing and names specifics. */
        data class Rejected(val message: String, val cause: Throwable? = null) : Result
    }

    /**
     * Open [dbFile] read-only, run the schema gate, and read the pack's configuration.
     *
     * Never throws for a bad pack: a refusal is a [Result.Rejected] value. §8 A1 requires "never a
     * crash, never a partial load" — and a loader that throws on a hostile file IS the crash.
     */
    fun open(dbFile: File): Result {
        if (!dbFile.isFile) return Result.Rejected("No pack database found at ${dbFile.name}.")

        var db: SQLiteDatabase? = null
        return try {
            db = SQLiteDatabase.openDatabase(dbFile.path, null, SQLiteDatabase.OPEN_READONLY)

            // ---- THE GATE. Before any content table is touched. ----
            val userVersion = db.rawQuery("PRAGMA user_version", null)
                .use { c -> if (c.moveToFirst()) c.getInt(0) else null }
            // pack_manifest.schema_version is TEXT (declared TEXT, stores "1"); user_version is INTEGER.
            // Both go through SchemaVersion.parse — never compared across representations. See
            // SchemaVersion.parse's KDoc for why this is a trap and not pedantry.
            val manifestVersionRaw = queryOne(db, "SELECT schema_version FROM pack_manifest LIMIT 1")

            when (val gate = SchemaVersion.evaluate(
                packManifestVersion = SchemaVersion.parse(manifestVersionRaw),
                userVersion = SchemaVersion.parse(userVersion?.toString()),
            )) {
                is SchemaVersion.GateResult.TooNew -> return Result.Rejected(gate.message)
                is SchemaVersion.GateResult.Malformed -> return Result.Rejected(gate.message)
                is SchemaVersion.GateResult.Ok -> Unit // fall through — safe to read
            }

            val manifest = readManifest(db)
                ?: return Result.Rejected("This pack has no manifest row, so the app cannot tell what exam it is for.")

            Result.Ok(
                LoadedPack(
                    manifest = manifest,
                    capabilities = readCapabilities(db, manifest),
                    subjects = readSubjects(db),
                    tags = readTags(db),
                )
            )
        } catch (e: SQLiteException) {
            // A corrupt/truncated file, or not a database at all. Both are "refused", not "crash".
            Result.Rejected("This file could not be opened as a StudyFeed pack. It may be corrupt or " +
                "still being copied.", e)
        } finally {
            db?.close()
        }
    }

    private fun readManifest(db: SQLiteDatabase): PackManifest? = db.rawQuery(
        """
        SELECT schema_version, pack_version, exam_code, exam_name, built_at, checksum,
               feature_flags_json, counts_json
        FROM pack_manifest LIMIT 1
        """.trimIndent(), null
    ).use { c ->
        if (!c.moveToFirst()) return null
        val schema = SchemaVersion.parse(c.getString(0)) ?: return null
        PackManifest(
            schemaVersion = schema,
            packVersion = c.getString(1).orEmpty(),
            examCode = c.getString(2).orEmpty(),
            examName = c.getString(3).orEmpty(),
            builtAt = c.getString(4).orEmpty(),
            // NOTE: pack_manifest.checksum — the CONTENT checksum over stable_keys, NOT the file
            // sha256 in manifest.json. Named contentChecksum so the two cannot be confused at a
            // call site. See PackManifest.contentChecksum's KDoc.
            contentChecksum = c.getString(5).orEmpty(),
            featureFlags = parseFlags(c.getString(6)),
            counts = parseCounts(c.getString(7)),
        )
    }

    /**
     * Resolve what this pack actually offers — **per pack, at runtime** (§8 A1 / PATCH 03; plan D5).
     *
     * **Rows are authoritative.** The pack's own `feature_flags_json` / `counts_json` are its
     * declaration: a fast hint, and a cross-check. Where they disagree with reality the pack is
     * malformed, so we trust the rows and record the disagreement rather than believing either blindly —
     * a flag claiming data that isn't there is exactly what produces a dead UI element with no error.
     *
     * This is not defensive over-engineering. It is the `multi_pack` contract: today's pack has blobs,
     * interlink and figures (C11b filled them), and a future pack may ship without them. An app that
     * assumes otherwise cannot swap its database.
     */
    private fun readCapabilities(db: SQLiteDatabase, manifest: PackManifest): PackCapabilities {
        val mismatches = mutableListOf<String>()

        fun resolve(table: String, flag: String): Boolean {
            val hasRows = tableHasRows(db, table)
            val declared = manifest.featureFlags[flag]
            if (declared != null && declared != hasRows) {
                mismatches += "pack declares $flag=$declared but $table " +
                    (if (hasRows) "has rows" else "is empty") + " — trusting the rows"
            }
            return hasRows
        }

        return PackCapabilities(
            hasFlashcards = resolve("flashcards", "has_flashcards"),
            hasReels = resolve("reels", "has_reels"),
            hasBlobs = resolve("text_blobs", "has_blobs"),
            hasInterlink = resolve("interlink_quizzes", "has_interlink"),
            hasFigures = resolve("figures", "has_figures"),
            hasDossiers = resolve("topic_pages", "has_dossiers"),
            hasConceptMap = resolve("concept_edges", "has_concept_map"),
            hasGeneratedMcqs = resolve("mcqs", "has_generated_mcqs"),
            declarationMismatches = mismatches,
        )
    }

    /**
     * `EXISTS` rather than `COUNT(*)`: it stops at the first row instead of scanning the whole table.
     * At 86,698 atoms and 32,957 feed_items that is the difference between instant and not.
     *
     * A missing table returns false, not a crash: an older pack legitimately may not have a table this
     * app knows about, and "absent" is the same answer as "empty" for the purpose of offering a feature.
     */
    private fun tableHasRows(db: SQLiteDatabase, table: String): Boolean = try {
        db.rawQuery("SELECT EXISTS(SELECT 1 FROM $table LIMIT 1)", null)
            .use { c -> c.moveToFirst() && c.getInt(0) == 1 }
    } catch (e: SQLiteException) {
        false
    }

    private fun readSubjects(db: SQLiteDatabase): List<Subject> = try {
        db.rawQuery("SELECT id, name, blueprint_weight, ord FROM subjects ORDER BY ord, id", null)
            .use { c ->
                buildList {
                    while (c.moveToNext()) {
                        add(Subject(c.getLong(0), c.getString(1).orEmpty(), c.getDouble(2), c.getInt(3)))
                    }
                }
            }
    } catch (e: SQLiteException) {
        emptyList()
    }

    private fun readTags(db: SQLiteDatabase): List<TagDef> = try {
        db.rawQuery("SELECT id, key, label, color, ord FROM tag_defs ORDER BY ord, id", null)
            .use { c ->
                buildList {
                    while (c.moveToNext()) {
                        add(TagDef(c.getLong(0), c.getString(1).orEmpty(), c.getString(2).orEmpty(),
                            c.getString(3), c.getInt(4)))
                    }
                }
            }
    } catch (e: SQLiteException) {
        emptyList()
    }

    private fun queryOne(db: SQLiteDatabase, sql: String): String? = try {
        db.rawQuery(sql, null).use { c -> if (c.moveToFirst()) c.getString(0) else null }
    } catch (e: SQLiteException) {
        null // no such table => malformed; the gate turns this into a proper refusal.
    }

    private fun parseFlags(json: String?): Map<String, Boolean> = try {
        JSONObject(json.orEmpty()).let { o ->
            o.keys().asSequence().associateWith { o.optBoolean(it, false) }
        }
    } catch (e: Exception) {
        emptyMap() // a pack may omit flags entirely; rows are authoritative anyway.
    }

    private fun parseCounts(json: String?): Map<String, Long> = try {
        JSONObject(json.orEmpty()).let { o ->
            o.keys().asSequence().associateWith { o.optLong(it, 0L) }
        }
    } catch (e: Exception) {
        emptyMap()
    }
}
